import{_ as i,l as p,o as e,c as n,v as r,p as l,x as t,d as s,i as d,S as E}from"./chunks/framework.InCnrqk-.js";const B=JSON.parse('{"title":"税收归宿","description":"","frontmatter":{"title":"税收归宿","date":"2026-09-08T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/tax-incidence.md","filePath":"econ/tax-incidence.md","lastUpdated":1789023840000}'),c={name:"econ/tax-incidence.md"};function _(h,a,m,A,u,b){const o=p("Mermaid");return e(),n("div",null,[a[1]||(a[1]=r('<h1 id="税收归宿" tabindex="-1">税收归宿 <a class="header-anchor" href="#税收归宿" aria-label="Permalink to &quot;税收归宿&quot;">​</a></h1><div class="epigraph"><p>税的负担不落在法定纳税人身上，而落在相对更无弹性的那一端。</p><footer>—— 据 Musgrave, The Theory of Public Finance, 1959；Harberger, The Incidence of the Corporation Income Tax, JPE, 1962 整理</footer></div><p><a href="/econ/lindahl-samuelson">上一课</a>（林达尔与萨缪尔森条件）。要用税去融资公共品，<a href="/econ/externality-pigou">庇古税</a>也已经把税当成纠正工具。缺口是会计：法令写「向买方征收」还是「向卖方征收」，并不决定谁的净价格动了多少。本课钉法定归宿与经济归宿的分离，以及弹性如何分摊 \\(t\\)，不重写萨缪尔森条件，也不把扭曲的福利成本展开成次优。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>从量税 \\(t\\) 插在买方支付价 \\(p_b\\) 与卖方实收价 \\(p_s\\) 之间，\\(p_b=p_s+t\\)。市场出清要求 \\(D(p_b)=S(p_s)\\)。法定归宿只指定谁把钱交给国库；经济归宿问 \\(p_b\\) 相对税前价格升了多少、\\(p_s\\) 降了多少。两者之和等于 \\(t\\)（局部、无收入效应的基准里）。</p><p>若需求完全无弹性，买方承担全部；供给完全无弹性，卖方承担全部。弹性有限时，负担按</p> \\[\\frac{\\mathrm{d}p_b}{\\mathrm{d}t}=\\frac{\\varepsilon_S}{\\varepsilon_S+\\varepsilon_D},\\qquad \\frac{\\mathrm{d}p_s}{\\mathrm{d}t}=-\\frac{\\varepsilon_D}{\\varepsilon_S+\\varepsilon_D} \\]<p>分摊（符号约定：\\(\\varepsilon_D\\) 取正的需求弹性绝对值）。法令把税票开给谁，只要楔子是 \\(t\\)，均衡净价与开票对象无关——这是局部市场的无关性。</p><h3 id="无关性不是无负担" tabindex="-1">无关性不是无负担 <a class="header-anchor" href="#无关性不是无负担" aria-label="Permalink to &quot;无关性不是无负担&quot;">​</a></h3><p>无关性说的是法定侧，不是「税没有人承担」。楔子仍在，剩余仍被切走一块。归宿分配的是这一块落在哪一侧，以及——一般均衡里——落在哪个要素、哪一代人。</p><p><span class="marginnote">图形：供给上移 \\(t\\) 与需求下移 \\(t\\) 给出同一对 \\((p_b,p_s)\\)。这就是法定无关。无弹性的那条曲线承担价格变动的大部分，因为它「无处可逃」。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>局部均衡：一种商品、收入效应忽略或收入用总额税补齐。工具是上述弹性公式。适用范围是税基小、与其他市场反馈弱。</p><p>一般均衡：Harberger 把公司税放进两部门、两要素模型。税使公司部门收缩，资本流向非公司部门，两部门资本回报一齐变，负担可以落到劳动或土地上，取决于替代弹性与要素密集。局部的「向资本征税、资本承担」在要素可流动时不成立。</p><p>总额税（lump-sum）没有楔子，归宿就是谁的预算被拿走，效率不动——那是<a href="/econ/welfare-theorems">第二定理</a>用过的转移。商品税、要素税才有归宿与超额负担两套账。本课主钉归宿；超额负担与「只纠正一个扭曲」留给下一课。</p>',15)),(e(),l(E,null,{default:t(()=>[d(o,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20STAT%5B%22%E6%B3%95%E5%AE%9A%EF%BC%9A%E5%90%91%E8%B0%81%E5%BC%80%E7%A5%A8%22%5D%20--%3E%20WEDGE%5B%22%E6%A5%94%E5%AD%90%20t%20%3D%20p_b%20%E2%88%92%20p_s%22%5D%0A%20%20WEDGE%20--%3E%20ELAST%5B%22%E5%BC%B9%E6%80%A7%E5%88%86%E6%91%8A%20dp_b%E3%80%81dp_s%22%5D%0A%20%20ELAST%20--%3E%20GE%5B%22%E4%B8%80%E8%88%AC%E5%9D%87%E8%A1%A1%EF%BC%9A%E8%A6%81%E7%B4%A0%E6%B5%81%E5%8A%A8%E6%94%B9%E8%90%BD%E7%82%B9%22%5D%0A%20%20WEDGE%20--%3E%20NEXT%5B%22%E5%90%8E%E8%AF%BE%EF%BC%9A%E6%A5%94%E5%AD%90%E8%BF%98%E7%A0%B4%E5%9D%8F%E5%85%B6%E4%BB%96%E5%88%87%E6%9D%A1%E4%BB%B6%22%5D%0A"})]),fallback:t(()=>[...a[0]||(a[0]=[s(" Loading... ",-1)])]),_:1})),a[2]||(a[2]=r('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>为什么弹性决定负担：税迫使交易量下降。谁更不能离开这个市场，谁就必须接受更差的净价。买方若有替代品，就逼卖方降 \\(p_s\\)；卖方若有其他用途，就逼买方抬 \\(p_b\\)。完全弹性的一端把税全部推走。</p><p>一般均衡多了要素价格这条通道。对资本征税像对「公司部门使用资本」征税；资本逃到另一部门，压低那边的边际产出，未征税部门的要素也受伤。归宿是一般均衡的比较静态，不是税表上的一行字。</p><h3 id="从量税与从价税" tabindex="-1">从量税与从价税 <a class="header-anchor" href="#从量税与从价税" aria-label="Permalink to &quot;从量税与从价税&quot;">​</a></h3><p>从价税 \\(t\\) 是买方价的一个比例，\\(p_b=(1+t)p_s\\)。弹性公式改写，但「无弹性的一端承担更多」不变。小税的无谓损失约 \\(\\tfrac12 t\\Delta q\\)，与归宿分割独立：负担落在谁身上是分配，三角形是效率。庇古税的「三角形」相对无税市场是校正有害活动，商品税的三角形是真损失。两种楔子不要用同一张福利账。</p><p>资本化：对土地征税，供给极无弹性，负担落在地主，地价一次性下跌，后人按税后价买入，不再「承担」税。归宿可以是资产价格，而不只是当期买卖价差。本课不把这句话写成证券微观结构：没有队列、没有做市存货。</p><p><span class="marginnote">垄断下法定无关性减弱：开票给买方或卖方可以改变边际收入曲线的写法，产量与税后剩余不必相同。本课基准是价格接受；寡头归宿留给博弈课的例子，不在这里重开古诺。</span></p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>局部公式忽略收入效应与交叉价格。所得税、增值税的归宿要进多市场。垄断下法定无关性减弱：开票对象可以改边际，因为卖方不是价格接受者。寡头更甚，那是后课博弈，不是本课的弹性除法。</p><p>归宿也不等于公平判断。无弹性的买方承担税，可能是穷人，也可能是必需品的短视需求；规范另要社会福利函数。下一课问：既然总额税不可用，留下的楔子应不应该按第一定理的切条件逐个对齐。</p><p>后课默认：讨论税时先分清法定与经济归宿；局部由弹性，全局由要素流动。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>法定纳税人不是负担者；楔子由相对弹性分摊。</li><li>向买方或卖方开票，局部均衡下净价相同。</li><li>Harberger：要素流动让税落到未征税市场。</li><li>总额税无楔子；商品税同时制造超额负担。</li><li>出处：Musgrave, 1959；Harberger, <em>JPE</em> 1962。</li></ul>',13))])}const D=i(c,[["render",_]]);export{B as __pageData,D as default};
